CREATE TYPE calculation_status AS ENUM ('COMPLETED','SUPERSEDED');
CREATE TABLE inspection_risk_factor_selections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE RESTRICT,risk_factor_id uuid NOT NULL REFERENCES risk_factors(id) ON DELETE RESTRICT,risk_factor_option_id uuid NOT NULL REFERENCES risk_factor_options(id) ON DELETE RESTRICT,version integer NOT NULL DEFAULT 1 CHECK(version>0),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(inspection_id,risk_factor_id));
CREATE TABLE inspection_calculations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),inspection_id uuid NOT NULL REFERENCES inspections(id) ON DELETE RESTRICT,calculation_number integer NOT NULL CHECK(calculation_number>0),status calculation_status NOT NULL DEFAULT 'COMPLETED',is_current boolean NOT NULL DEFAULT true,bpm_template_version_id uuid NOT NULL REFERENCES bpm_template_versions(id) ON DELETE RESTRICT,risk_rule_version_id uuid NOT NULL REFERENCES risk_rule_versions(id) ON DELETE RESTRICT,bpm_numerator numeric(12,4) NOT NULL CHECK(bpm_numerator>=0),bpm_denominator integer NOT NULL CHECK(bpm_denominator>0),bpm_percentage numeric(7,4) NOT NULL CHECK(bpm_percentage>=0 AND bpm_percentage<=100),product_risk_score numeric(4,2) NOT NULL CHECK(product_risk_score IN(1,2,3)),establishment_risk_score numeric(8,4) NOT NULL CHECK(establishment_risk_score>=0),total_risk_score numeric(10,4) NOT NULL CHECK(total_risk_score>=0),frequency inspection_frequency NOT NULL,frequency_range_id uuid NOT NULL REFERENCES inspection_frequency_ranges(id) ON DELETE RESTRICT,calculation_reason text,calculated_by_user_id uuid NOT NULL REFERENCES users(id) ON DELETE RESTRICT,calculated_at timestamptz NOT NULL DEFAULT clock_timestamp(),superseded_at timestamptz,superseded_by_user_id uuid REFERENCES users(id) ON DELETE RESTRICT,UNIQUE(inspection_id,calculation_number),CHECK(total_risk_score=product_risk_score*establishment_risk_score),CHECK((status='COMPLETED' AND is_current AND superseded_at IS NULL AND superseded_by_user_id IS NULL) OR (status='SUPERSEDED' AND NOT is_current AND superseded_at IS NOT NULL AND superseded_by_user_id IS NOT NULL)));
CREATE UNIQUE INDEX inspection_calculations_one_current_idx ON inspection_calculations(inspection_id) WHERE is_current;
CREATE TABLE inspection_calculation_bpm_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),calculation_id uuid NOT NULL REFERENCES inspection_calculations(id) ON DELETE RESTRICT,bpm_item_id uuid NOT NULL REFERENCES bpm_template_items(id) ON DELETE RESTRICT,display_code_snapshot varchar(120),response_value bpm_response_value NOT NULL,response_score numeric(3,2),is_applicable boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(calculation_id,bpm_item_id),CHECK((is_applicable AND response_value<>'NA' AND response_score IN(0,0.5,1)) OR (NOT is_applicable AND response_value='NA' AND response_score IS NULL)));
CREATE TABLE inspection_calculation_factor_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),calculation_id uuid NOT NULL REFERENCES inspection_calculations(id) ON DELETE RESTRICT,risk_factor_id uuid NOT NULL REFERENCES risk_factors(id) ON DELETE RESTRICT,factor_code_snapshot varchar(80) NOT NULL,factor_name_snapshot varchar(160) NOT NULL,weight_snapshot numeric(6,4) NOT NULL,risk_factor_option_id uuid NOT NULL REFERENCES risk_factor_options(id) ON DELETE RESTRICT,option_code_snapshot varchar(80) NOT NULL,option_label_snapshot varchar(300) NOT NULL,selected_score_snapshot numeric(4,2) NOT NULL,weighted_contribution numeric(10,4) NOT NULL,sort_order_snapshot integer NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(calculation_id,risk_factor_id));
CREATE TABLE inspection_calculation_food_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),calculation_id uuid NOT NULL REFERENCES inspection_calculations(id) ON DELETE RESTRICT,inspection_food_snapshot_id uuid NOT NULL REFERENCES inspection_food_snapshots(id) ON DELETE RESTRICT,food_risk_subcategory_id uuid NOT NULL REFERENCES food_risk_subcategories(id) ON DELETE RESTRICT,category_code_snapshot varchar(120) NOT NULL,subcategory_name_snapshot varchar(700) NOT NULL,microbiological_risk_snapshot microbiological_risk,risk_score_snapshot smallint,is_applicable boolean NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(calculation_id,inspection_food_snapshot_id),CHECK((is_applicable AND risk_score_snapshot IN(1,2,3) AND microbiological_risk_snapshot IS NOT NULL) OR (NOT is_applicable AND risk_score_snapshot IS NULL AND microbiological_risk_snapshot IS NULL)));
CREATE TABLE inspection_calculation_frequency_snapshots(calculation_id uuid PRIMARY KEY REFERENCES inspection_calculations(id) ON DELETE RESTRICT,frequency_range_id uuid NOT NULL REFERENCES inspection_frequency_ranges(id) ON DELETE RESTRICT,lower_bound_snapshot numeric(8,2) NOT NULL,upper_bound_snapshot numeric(8,2),lower_inclusive_snapshot boolean NOT NULL,upper_inclusive_snapshot boolean NOT NULL,frequency inspection_frequency NOT NULL,label_snapshot varchar(100) NOT NULL,created_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION inspection_factor_selection_guard() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE rule_id uuid; factor_rule uuid; option_factor uuid; iid uuid; BEGIN iid:=COALESCE(NEW.inspection_id,OLD.inspection_id); IF NOT inspection_is_editable(iid) THEN RAISE EXCEPTION 'inspection is not editable'; END IF; IF TG_OP IN('INSERT','UPDATE') THEN SELECT risk_rule_version_id INTO rule_id FROM inspections WHERE id=NEW.inspection_id; SELECT risk_rule_version_id INTO factor_rule FROM risk_factors WHERE id=NEW.risk_factor_id; SELECT risk_factor_id INTO option_factor FROM risk_factor_options WHERE id=NEW.risk_factor_option_id; IF factor_rule IS DISTINCT FROM rule_id OR option_factor IS DISTINCT FROM NEW.risk_factor_id THEN RAISE EXCEPTION 'risk factor selection does not belong to inspection rule'; END IF; END IF; RETURN COALESCE(NEW,OLD); END $$;
CREATE OR REPLACE FUNCTION calculation_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'calculations are historical and cannot be deleted'; END IF; IF TG_OP='INSERT' THEN IF NEW.status<>'COMPLETED' OR NOT NEW.is_current THEN RAISE EXCEPTION 'new calculation must be current and completed'; END IF; RETURN NEW; END IF; IF OLD.status<>'COMPLETED' OR NOT OLD.is_current OR NEW.status<>'SUPERSEDED' OR NEW.is_current OR NEW.superseded_at IS NULL OR NEW.superseded_by_user_id IS NULL OR NEW.inspection_id<>OLD.inspection_id OR NEW.calculation_number<>OLD.calculation_number OR NEW.bpm_template_version_id<>OLD.bpm_template_version_id OR NEW.risk_rule_version_id<>OLD.risk_rule_version_id OR NEW.bpm_numerator<>OLD.bpm_numerator OR NEW.bpm_denominator<>OLD.bpm_denominator OR NEW.bpm_percentage<>OLD.bpm_percentage OR NEW.product_risk_score<>OLD.product_risk_score OR NEW.establishment_risk_score<>OLD.establishment_risk_score OR NEW.total_risk_score<>OLD.total_risk_score OR NEW.frequency<>OLD.frequency OR NEW.frequency_range_id<>OLD.frequency_range_id THEN RAISE EXCEPTION 'calculation history immutable'; END IF; RETURN NEW; END $$;
CREATE OR REPLACE FUNCTION calculation_snapshot_guard() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'calculation snapshots are immutable'; END $$;
CREATE OR REPLACE FUNCTION recalculate_inspection(p_inspection_id uuid,p_calculated_by_user_id uuid,p_reason text DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql AS $$ DECLARE ins inspections%ROWTYPE; product_score numeric(4,2); establishment_score numeric(8,4); total_score numeric(10,4); numerator numeric(12,4); denominator integer; range_row inspection_frequency_ranges%ROWTYPE; next_number integer; calc_id uuid; BEGIN SELECT * INTO ins FROM inspections WHERE id=p_inspection_id FOR UPDATE; IF NOT FOUND OR ins.status<>'SUBMITTED' THEN RAISE EXCEPTION 'calculation requires submitted inspection'; END IF; IF EXISTS(SELECT 1 FROM bpm_template_items i WHERE i.template_version_id=ins.bpm_template_version_id AND i.item_kind='CRITERION' AND i.is_evaluable AND NOT EXISTS(SELECT 1 FROM inspection_bpm_responses r WHERE r.inspection_id=ins.id AND r.bpm_item_id=i.id)) THEN RAISE EXCEPTION 'all evaluable BPM items require responses'; END IF; IF (SELECT count(*) FROM inspection_risk_factor_selections s JOIN risk_factors f ON f.id=s.risk_factor_id WHERE s.inspection_id=ins.id AND f.risk_rule_version_id=ins.risk_rule_version_id)<>6 THEN RAISE EXCEPTION 'all six risk factors require selections'; END IF; SELECT max(risk_score_snapshot)::numeric INTO product_score FROM inspection_food_snapshots WHERE inspection_id=ins.id AND risk_score_snapshot IS NOT NULL; IF product_score IS NULL THEN RAISE EXCEPTION 'no applicable food risk snapshot'; END IF; SELECT coalesce(sum(CASE r.response_value WHEN 'C' THEN 1 WHEN 'CP' THEN .5 ELSE 0 END),0),count(*) FILTER(WHERE r.response_value<>'NA') INTO numerator,denominator FROM inspection_bpm_responses r WHERE r.inspection_id=ins.id; IF denominator=0 THEN RAISE EXCEPTION 'no applicable BPM responses'; END IF; SELECT sum(o.score*f.weight) INTO establishment_score FROM inspection_risk_factor_selections s JOIN risk_factors f ON f.id=s.risk_factor_id JOIN risk_factor_options o ON o.id=s.risk_factor_option_id WHERE s.inspection_id=ins.id; total_score:=product_score*establishment_score; SELECT * INTO range_row FROM inspection_frequency_ranges fr WHERE fr.risk_rule_version_id=ins.risk_rule_version_id AND (total_score>fr.lower_bound OR (fr.lower_inclusive AND total_score=fr.lower_bound)) AND (fr.upper_bound IS NULL OR total_score<fr.upper_bound OR (fr.upper_inclusive AND total_score=fr.upper_bound)); IF NOT FOUND THEN RAISE EXCEPTION 'no frequency range for total risk'; END IF; UPDATE inspection_calculations SET status='SUPERSEDED',is_current=false,superseded_at=clock_timestamp(),superseded_by_user_id=p_calculated_by_user_id WHERE inspection_id=ins.id AND is_current; SELECT coalesce(max(calculation_number),0)+1 INTO next_number FROM inspection_calculations WHERE inspection_id=ins.id; INSERT INTO inspection_calculations(inspection_id,calculation_number,bpm_template_version_id,risk_rule_version_id,bpm_numerator,bpm_denominator,bpm_percentage,product_risk_score,establishment_risk_score,total_risk_score,frequency,frequency_range_id,calculation_reason,calculated_by_user_id) VALUES(ins.id,next_number,ins.bpm_template_version_id,ins.risk_rule_version_id,numerator,denominator,numerator/denominator*100,product_score,establishment_score,total_score,range_row.frequency,range_row.id,p_reason,p_calculated_by_user_id) RETURNING id INTO calc_id; INSERT INTO inspection_calculation_bpm_snapshots(calculation_id,bpm_item_id,display_code_snapshot,response_value,response_score,is_applicable) SELECT calc_id,r.bpm_item_id,i.display_code,r.response_value,CASE r.response_value WHEN 'C' THEN 1 WHEN 'CP' THEN .5 WHEN 'IT' THEN 0 ELSE NULL END,r.response_value<>'NA' FROM inspection_bpm_responses r JOIN bpm_template_items i ON i.id=r.bpm_item_id WHERE r.inspection_id=ins.id; INSERT INTO inspection_calculation_factor_snapshots(calculation_id,risk_factor_id,factor_code_snapshot,factor_name_snapshot,weight_snapshot,risk_factor_option_id,option_code_snapshot,option_label_snapshot,selected_score_snapshot,weighted_contribution,sort_order_snapshot) SELECT calc_id,f.id,f.code,f.name,f.weight,o.id,o.code,o.label,o.score,o.score*f.weight,f.sort_order FROM inspection_risk_factor_selections s JOIN risk_factors f ON f.id=s.risk_factor_id JOIN risk_factor_options o ON o.id=s.risk_factor_option_id WHERE s.inspection_id=ins.id; INSERT INTO inspection_calculation_food_snapshots(calculation_id,inspection_food_snapshot_id,food_risk_subcategory_id,category_code_snapshot,subcategory_name_snapshot,microbiological_risk_snapshot,risk_score_snapshot,is_applicable) SELECT calc_id,x.id,x.food_risk_subcategory_id,x.category_code_snapshot,x.subcategory_name_snapshot,x.microbiological_risk_snapshot,x.risk_score_snapshot,x.risk_score_snapshot IS NOT NULL FROM inspection_food_snapshots x WHERE x.inspection_id=ins.id; INSERT INTO inspection_calculation_frequency_snapshots(calculation_id,frequency_range_id,lower_bound_snapshot,upper_bound_snapshot,lower_inclusive_snapshot,upper_inclusive_snapshot,frequency,label_snapshot) VALUES(calc_id,range_row.id,range_row.lower_bound,range_row.upper_bound,range_row.lower_inclusive,range_row.upper_inclusive,range_row.frequency,range_row.label); RETURN calc_id; END $$;
CREATE TRIGGER inspection_factor_selections_guard BEFORE INSERT OR UPDATE OR DELETE ON inspection_risk_factor_selections FOR EACH ROW EXECUTE FUNCTION inspection_factor_selection_guard(); CREATE TRIGGER inspection_factor_selections_version BEFORE UPDATE ON inspection_risk_factor_selections FOR EACH ROW EXECUTE FUNCTION set_updated_at_and_version(); CREATE TRIGGER calculations_guard BEFORE INSERT OR UPDATE OR DELETE ON inspection_calculations FOR EACH ROW EXECUTE FUNCTION calculation_guard(); CREATE TRIGGER calculation_bpm_snapshots_guard BEFORE UPDATE OR DELETE ON inspection_calculation_bpm_snapshots FOR EACH ROW EXECUTE FUNCTION calculation_snapshot_guard(); CREATE TRIGGER calculation_factor_snapshots_guard BEFORE UPDATE OR DELETE ON inspection_calculation_factor_snapshots FOR EACH ROW EXECUTE FUNCTION calculation_snapshot_guard(); CREATE TRIGGER calculation_food_snapshots_guard BEFORE UPDATE OR DELETE ON inspection_calculation_food_snapshots FOR EACH ROW EXECUTE FUNCTION calculation_snapshot_guard(); CREATE TRIGGER calculation_frequency_snapshots_guard BEFORE UPDATE OR DELETE ON inspection_calculation_frequency_snapshots FOR EACH ROW EXECUTE FUNCTION calculation_snapshot_guard();
